//
// Extension -> human file-type chips (category + format) and search aliases.
// Used for friendly file tags and to make files findable by their type
// ("blender", "3d", "photoshop"). Classification for *routing/extraction*
// still happens in relic-sift by magic bytes; this map is display/search only.

/// One file extension's display chips and extra search terms.
class FileType {
  final String category; // broad chip, e.g. "3D"
  final String format; // specific chip, e.g. "Blender"
  final List<String> aliases; // extra lowercase search terms
  const FileType(this.category, this.format, this.aliases);
}

String? _extOf(String? filename) {
  if (filename == null) return null;
  final name = filename.toLowerCase();
  final dot = name.lastIndexOf('.');
  if (dot < 0 || dot == name.length - 1) return null;
  return name.substring(dot + 1);
}

/// The file-type record for a filename's extension, or null if unknown.
FileType? fileTypeFor(String? filename) => kFileTypeByExt[_extOf(filename)];

/// Display chips for a file: [category, format], collapsed to one when equal.
List<String> fileTypeChips(String? filename) {
  final ft = fileTypeFor(filename);
  if (ft == null) return const [];
  if (ft.format.toLowerCase() == ft.category.toLowerCase()) return [ft.category];
  return [ft.category, ft.format];
}

/// Lowercase terms appended to the search index so a file is findable by its
/// type words (category, format, and aliases).
List<String> fileTypeSearchTerms(String? filename) {
  final ft = fileTypeFor(filename);
  if (ft == null) return const [];
  return [ft.category.toLowerCase(), ft.format.toLowerCase(), ...ft.aliases];
}

/// Raster formats the Flutter engine can decode and show inline. Excludes
/// things like heic/tiff/psd/svg/raw that need conversion first.
const _displayableImageExts = {
  'png', 'jpg', 'jpeg', 'jfif', 'jpe', 'gif', 'webp', 'bmp', 'dib', 'wbmp',
};

/// True for an image file Relic that can be shown directly (thumbnail + viewer),
/// detected by its declared MIME or its extension.
bool isDisplayableImageFile(String? filename, String? mime) {
  switch ((mime ?? '').toLowerCase()) {
    case 'image/png':
    case 'image/jpeg':
    case 'image/jpg':
    case 'image/gif':
    case 'image/webp':
    case 'image/bmp':
      return true;
  }
  final ext = _extOf(filename);
  return ext != null && _displayableImageExts.contains(ext);
}

